NULL, NULL, '2', NULL, '2', NULL, NULL, NULL, '2', NULL, '2023-01-17', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'EL ÚLTIMO ACTO PROCESAL REGISTRADO ES LA ADMISIÓN DE LA DEMANDA. EN FECHA 16/08/2022 EL TRIBUNAL LABORAL RECIBE OFICIO POR INCOMPETENCIA POR PARTE DEL TRIBUNAL LABORAL FEDERAL DE ASUNTOS INDIVIDUALES CON SEDE EN ZACATECAS, EN MISMA FECHA EL TRIBUNAL LABORAL ZACATECAS SE DECLARA INCOMPETENTE, SE REMITE EL ASUNTO AL TRIBUNAL COLEGIADO DEL VIGÉSIMO TERCER CIRCUITO. EN FECHA 20/09/2022 EL TRIBUNAL COLEGIADO DE CIRCUITO DETERMINA QUE EL ORGANO COMPETENTE LO ES EL TRIBUNAL LABORAL DE ZACATECAS.', null , null , null , null );
